// Payload from 511 (via sms/command/received): { messages, messageCount, latest }
// Handle parsed object, JSON string, or Buffer (mqtt_in datatype varies)
let payload = msg.payload;
if (Buffer.isBuffer(payload)) payload = payload.toString('utf8');
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (e) { return null; }
}
const latest = (payload && payload.latest) || null;
if (!latest || latest.from == null || latest.from === '' || typeof latest.text !== 'string') {
    return null;
}

const from = String(latest.from).trim();
let rawText = (latest.text || '').trim();
if (!rawText) {
    return null;
}

// Gateway may send raw modem format: +CMGR: "REC READ",...\n/command
// Extract actual message line (skip +CMGR / AT response lines)
const lines = rawText.split(/[\r\n]+/).map(s => s.trim()).filter(s => s.length > 0);
const commandLine = lines.find(l => !/^\+[A-Z]/.test(l) && !l.startsWith('AT')) || lines[lines.length - 1] || rawText;
rawText = commandLine;

// Normalize phone: digits only for gateway (510 strips +)
const digitsFrom = from.replace(/\D/g, '');
const replyTo = digitsFrom.length > 0 ? digitsFrom : from;

// Parse command: with or without /, case-insensitive, trim
const parts = rawText.split(/\s+/);
const rawCommand = (parts[0] || '').toLowerCase().replace(/^\//, '').replace(/_/g, '_').trim();
const args = parts.slice(1);

// Authorization check
const allowedPhones = flow.get('sms_allowed_phones');
if (Array.isArray(allowedPhones) && allowedPhones.length > 0) {
    const allowed = allowedPhones.some(p => {
        const normP = String(p).replace(/\D/g, '');
        if (!normP) return false;
        if (digitsFrom === normP) return true;
        const longer = digitsFrom.length >= normP.length ? digitsFrom : normP;
        const shorter = digitsFrom.length < normP.length ? digitsFrom : normP;
        return longer.endsWith(shorter) || shorter.endsWith(longer);
    });
    if (!allowed) {
        node.warn('SMS from unauthorized number: ' + from + ' (digits: ' + digitsFrom + ')');
        return null;
    }
}

msg.sms = {
    from: replyTo,
    command: rawCommand,
    args: args,
    originalText: rawText
};
msg.payload = latest;

return msg;

const cmd = msg.sms.command;
const args = msg.sms.args;
const to = msg.sms.from;

// Helper to send SMS reply (payload must be JSON string for gateway)
function reply(text) {
    const smsPayload = JSON.stringify({ to: to, text: text });
    return [{ payload: smsPayload, topic: 'sms/gateway/command/send' }, null];
}

// Helper to send MQTT + reply
function mqttAndReply(topic, payload, replyText) {
    const smsPayload = JSON.stringify({ to: to, text: replyText });
    return [
        { payload: smsPayload, topic: 'sms/gateway/command/send' },
        { payload: payload, topic: topic }
    ];
}

// ==================== HELP ====================
if (cmd === 'help' || cmd === 'commands' || cmd === 'start') {
    return reply('Cmds: HELP, STATUS, GATE_OPEN, GATE_STATUS, SLIDING_OPEN/CLOSE, SECONDARY_OPEN/CLOSE, GARDEN_ON/OFF, LIGHTS_ON/OFF, PUMP_START/STOP, AQUARIUM_ON/OFF, SMS_STATUS, SMS_LOG');
}

// ==================== SERVER ====================
if (cmd === 'boot') {
    const server = (args[0] || 'dell').toLowerCase();
    if (server === 'hp' || server === 'dl360p') {
        return mqttAndReply('hp/dl360p/command/boot', { action: 'boot', method: 'ilo' }, 'Booting HP DL360p via iLO...');
    } else {
        return mqttAndReply('dell/t310/command/boot', { action: 'boot', method: 'wol' }, 'Booting Dell T310 via WoL...');
    }
}
if (cmd === 'shutdown' || cmd === 'stop') {
    const server = (args[0] || 'dell').toLowerCase();
    if (server === 'hp' || server === 'dl360p') {
        return mqttAndReply('hp/dl360p/command/shutdown', { action: 'shutdown', type: 'graceful', timeout: 300 }, 'Graceful shutdown HP DL360p...');
    } else {
        return mqttAndReply('dell/t310/command/shutdown', { action: 'shutdown', type: 'graceful', timeout: 300 }, 'Graceful shutdown Dell T310...');
    }
}
if (cmd === 'force' || cmd === 'force_shutdown') {
    const server = (args[0] || 'dell').toLowerCase();
    if (server === 'hp' || server === 'dl360p') {
        return mqttAndReply('hp/dl360p/command/shutdown', { action: 'shutdown', type: 'force' }, 'FORCE shutdown HP DL360p!');
    } else {
        return mqttAndReply('dell/t310/command/shutdown', { action: 'shutdown', type: 'force' }, 'FORCE shutdown Dell T310!');
    }
}
if (cmd === 'status' || cmd === 'state') {
    const dell = flow.get('status_dell_t310_status') || {};
    const hp = flow.get('status_hp_dl360p_status') || {};
    const dellState = (dell.server_state || 'unknown').toUpperCase();
    const hpState = (hp.server_state || 'unknown').toUpperCase();
    return reply('Server Status: Dell T310: ' + dellState + ', HP DL360p: ' + hpState);
}

// ==================== MAIN GATE ====================
if (cmd === 'gate_open' || cmd === 'gate') {
    return mqttAndReply('MainGate/CMD/Relay2', 'ON', 'Opening Main Gate (Relay 2)...');
}
if (cmd === 'gate_status') {
    const g = (flow.get('gate_state') || {}).mainGate || {};
    return reply('Main Gate: Power=' + (g.power||'?') + ', R1=' + (g.relay1||'?') + ', R2=' + (g.relay2||'?') + ', R3=' + (g.relay3||'?') + ', R4=' + (g.relay4||'?'));
}

// ==================== SLIDING GATE ====================
if (cmd === 'sliding_open') {
    return mqttAndReply('cmnd/automatizare_poarta/Power1', true, 'Opening Sliding Gate (R1)...');
}
if (cmd === 'sliding_close') {
    return mqttAndReply('cmnd/automatizare_poarta/Power2', true, 'Closing Sliding Gate (R2)...');
}
if (cmd === 'sliding_trigger') {
    return mqttAndReply('cmnd/automatizare_poarta/Power3', true, 'Triggering Sliding Gate (R3)...');
}
if (cmd === 'sliding_status') {
    const s = flow.get('sliding_gate_state') || {};
    return reply('Sliding Gate: R1=' + (s.relay1||'?') + ', R2=' + (s.relay2||'?') + ', R3=' + (s.relay3||'?') + ', R4=' + (s.relay4||'?'));
}

// ==================== SECONDARY GATE ====================
if (cmd === 'secondary_open') {
    return mqttAndReply('SecondGate/CMD/Relay2', 'ON', 'Opening Secondary Gate (R2)...');
}
if (cmd === 'secondary_close') {
    return mqttAndReply('SecondGate/CMD/Relay1', 'ON', 'Closing Secondary Gate (R1)...');
}
if (cmd === 'secondary_trigger') {
    return mqttAndReply('SecondGate/CMD/Relay3', 'ON', 'Triggering Secondary Gate (R3)...');
}
if (cmd === 'secondary_stop') {
    return mqttAndReply('SecondGate/CMD/Relay4', 'ON', 'Stopping Secondary Gate (R4)...');
}
if (cmd === 'secondary_light_left') {
    return mqttAndReply('SecondGate/CMD/Relay5', 'ON', 'Left Light ON (R5, 120s)...');
}
if (cmd === 'secondary_light_right') {
    return mqttAndReply('SecondGate/CMD/Relay6', 'ON', 'Right Light ON (R6, 120s)...');
}
if (cmd === 'secondary_status') {
    const s = flow.get('secondary_gate_state') || {};
    return reply('Secondary Gate: R1=' + (s.relay1||'?') + ', R2=' + (s.relay2||'?') + ', R3=' + (s.relay3||'?') + ', R4=' + (s.relay4||'?') + ', R5(L)=' + (s.relay5||'?') + ', R6(R)=' + (s.relay6||'?'));
}

// ==================== GARDEN POWER ====================
if (cmd === 'garden_on') {
    return mqttAndReply('cmnd/sonoffPower320D_afara/Power', 'ON', 'Garden power ON...');
}
if (cmd === 'garden_off') {
    return mqttAndReply('cmnd/sonoffPower320D_afara/Power', 'OFF', 'Garden power OFF...');
}
if (cmd === 'garden_toggle') {
    return mqttAndReply('cmnd/sonoffPower320D_afara/Power', 'TOGGLE', 'Garden power TOGGLE...');
}
if (cmd === 'garden_status') {
    const g = global.get('garden_power_state') || {};
    return reply('Garden Power: ' + (g.powerStatus||'?') + ', V=' + (g.voltage||'?') + 'V, A=' + (g.current||'?') + 'A, W=' + (g.power||'?') + 'W');
}

// ==================== GARDEN LIGHTS ====================
if (cmd === 'lights_on') {
    // Broadcast to all 16 lights
    const msgs = [];
    for (let i = 1; i <= 12; i++) {
        msgs.push({ topic: 'GardenAutomationLights/CMD/Relay' + i, payload: 'ON' });
    }
    for (let i = 1; i <= 4; i++) {
        msgs.push({ topic: 'cmnd/frontHousePower/POWER' + i, payload: 'ON' });
    }
    node.send([{ payload: JSON.stringify({ to: to, text: 'All 16 garden lights ON...' }), topic: 'sms/gateway/command/send' }, null]);
    for (const m of msgs) {
        node.send([null, m]);
    }
    return null;
}
if (cmd === 'lights_off') {
    const msgs = [];
    for (let i = 1; i <= 12; i++) {
        msgs.push({ topic: 'GardenAutomationLights/CMD/Relay' + i, payload: 'OFF' });
    }
    for (let i = 1; i <= 4; i++) {
        msgs.push({ topic: 'cmnd/frontHousePower/POWER' + i, payload: 'OFF' });
    }
    node.send([{ payload: JSON.stringify({ to: to, text: 'All 16 garden lights OFF...' }), topic: 'sms/gateway/command/send' }, null]);
    for (const m of msgs) {
        node.send([null, m]);
    }
    return null;
}
if (cmd === 'lights_status') {
    const st = global.get('garden_lights_state') || {};
    let on = 0, off = 0;
    for (let i = 1; i <= 16; i++) {
        if (st['light_' + i] === 'ON') on++;
        else if (st['light_' + i] === 'OFF') off++;
    }
    return reply('Garden Lights: ' + on + ' ON, ' + off + ' OFF, ' + (16 - on - off) + ' unknown');
}

// ==================== WATER PUMP ====================
if (cmd === 'pump_start') {
    return mqttAndReply('cmnd/pompaApa/Power1', 'ON', 'Water pump starting...');
}
if (cmd === 'pump_stop') {
    return mqttAndReply('cmnd/pompaApa/Power1', 'OFF', 'Water pump stopping...');
}
if (cmd === 'pump_drain') {
    return mqttAndReply('cmnd/pompaApa/Power2', 'ON', 'Drain water (10s pulse)...');
}
if (cmd === 'pump_trench1_on') {
    return mqttAndReply('cmnd/pompaApa/Power3', 'ON', 'Feed Trench 1 ON...');
}
if (cmd === 'pump_trench1_off') {
    return mqttAndReply('cmnd/pompaApa/Power3', 'OFF', 'Feed Trench 1 OFF...');
}
if (cmd === 'pump_trench2_on') {
    return mqttAndReply('cmnd/pompaApa/Power4', 'ON', 'Feed Trench 2 ON...');
}
if (cmd === 'pump_trench2_off') {
    return mqttAndReply('cmnd/pompaApa/Power4', 'OFF', 'Feed Trench 2 OFF...');
}
if (cmd === 'pump_status') {
    const p = global.get('water_pump_state') || {};
    return reply('Pump: Power=' + (p.pump_power||'?') + ', Drain=' + (p.drain_water||'?') + ', T1=' + (p.feed_trench_1||'?') + ', T2=' + (p.feed_trench_2||'?'));
}

// ==================== AQUARIUM ====================
if (cmd === 'aquarium_on') {
    return mqttAndReply('cmnd/sursaAcvariu/POWER', 'ON', 'Aquarium light ON...');
}
if (cmd === 'aquarium_off') {
    return mqttAndReply('cmnd/sursaAcvariu/POWER', 'OFF', 'Aquarium light OFF...');
}
if (cmd === 'aquarium_toggle') {
    return mqttAndReply('cmnd/sursaAcvariu/POWER', 'TOGGLE', 'Aquarium light toggled...');
}
if (cmd === 'aquarium_status') {
    const a = global.get('aquarium_state') || {};
    return reply('Aquarium Light: ' + (a.light_power || 'unknown'));
}

// ==================== SMS GATEWAY ====================
if (cmd === 'sms_status') {
    const st = flow.get('status_metadata_sms_gateway') || {};
    const sd = flow.get('sms_gateway_status') || {};
    let text = 'SMS Gateway: WiFi=' + (sd.wifi||'?') + ', MQTT=' + (sd.mqtt||'?') + ', GSM=' + (sd.gsm||'?');
    if (st.lastReportedMs) {
        const sec = Math.floor((Date.now() - st.lastReportedMs) / 1000);
        if (sec < 60) text += '. ' + sec + 's ago';
        else text += '. ' + Math.floor(sec/60) + 'm ago';
    }
    return reply(text);
}
if (cmd === 'sms_log') {
    const log = flow.get('sms_message_log') || [];
    if (log.length === 0) return reply('No SMS messages received yet.');
    const recent = log.slice(0, 3);
    let text = 'Recent SMS (' + log.length + ' total): ';
    recent.forEach((m, i) => {
        text += (i+1) + '. From ' + m.from + ': ' + (m.text||'').substring(0, 30) + ' ';
    });
    if (text.length > 300) text = text.substring(0, 297) + '...';
    return reply(text);
}

// ==================== UNKNOWN ====================
return reply('Unknown: ' + (msg.sms.originalText || '').substring(0, 60) + '. Text HELP for commands.');
